def data(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * y[i] if (j + y[i]) % 2 == 0 else -0.3 * y[i])
    return X, y

X, y = data(60, 4, 3)
Q = X[:6] + 0.1
R = 1e-9
A = 1e-11

def cq(tag: str, q, dec, proba, pred, means):
    check(close(q.decision_function(Q), dec, R, A), tag + " dec")
    check(close(q.predict_proba(Q), proba, R, 1e-14), tag + " proba")
    check(close(q.predict(X), pred), tag + " pred")
    check(close(q.means_, means, R, A), tag + " means")

cq("qda svd", QDA().fit(X, y), qda_svd_dec, qda_svd_proba, qda_svd_pred, qda_svd_means)
cq("qda eig", QDA(solver="eigen", reg_param=0.0).fit(X, y), qda_eig_dec, qda_eig_proba, qda_eig_pred, qda_eig_means)
qr = QDA(reg_param=0.3, store_covariance=True).fit(X, y)
cq("qda reg", qr, qda_reg_dec, qda_reg_proba, qda_reg_pred, qda_reg_means)
check(close(qr.covariance_[0], qda_reg_cov0, R, A), "qda reg cov")
cq("qda shr", QDA(solver="eigen", shrinkage="auto").fit(X, y), qda_shr_dec, qda_shr_proba, qda_shr_pred, qda_shr_means)
cq("qda shf", QDA(solver="eigen", shrinkage=0.2, priors=[0.2, 0.3, 0.5]).fit(X, y), qda_shf_dec, qda_shf_proba, qda_shf_pred, qda_shf_means)
m2 = y < 2
check(close(QDA().fit(X[m2], y[m2]).decision_function(Q), qda_bin_dec, R, A), "qda binary dec")
check(close(LDA().fit(X, y).predict_log_proba(Q), lda_logp, R, A), "lda log proba")

