for i in range(6):
    for j in range(3):
        Z[i, j] += 6.0
m = MinCovDet(random_state=1).fit(Z)
check(close(m.raw_location_, mcd_rloc, R, A), "mcd raw loc"); check(close(m.raw_covariance_, mcd_rcov, R, A), "mcd raw cov")
check(close(m.raw_support_, mcd_rsup), "mcd raw support"); check(close(m.location_, mcd_loc, R, A), "mcd loc")
check(close(m.covariance_, mcd_cov, R, A), "mcd cov"); check(close(m.support_, mcd_sup), "mcd support")
check(close(m.dist_, mcd_dist, 1e-8, A), "mcd dist")
m1 = MinCovDet(random_state=2, support_fraction=0.8).fit(Z[:, :1])
check(close(m1.location_, mcd1_loc, R, A), "mcd 1d loc"); check(close(m1.covariance_, mcd1_cov, R, A), "mcd 1d cov")
e = EllipticEnvelope(random_state=3, contamination=0.1).fit(Z)
check(close([e.offset_], [ee_off], 1e-8, A), "ee offset"); check(close(e.decision_function(Z[:10]), ee_dec, 1e-8, 1e-9), "ee dec")
check(close(e.predict(Z), ee_pred), "ee pred")
g = GraphicalLasso(alpha=0.1).fit(Z)
check(close(g.covariance_, gl_cov, 1e-8, 1e-10), "glasso cov"); check(close(g.precision_, gl_prec, 1e-8, 1e-10), "glasso prec")
check(g.n_iter_ == gl_it, "glasso n_iter")
c, pr = graphical_lasso(np.cov(Z.T, bias=True), alpha=0.3)
check(close(c, glf_cov, 1e-8, 1e-10), "graphical_lasso cov"); check(close(pr, glf_prec, 1e-8, 1e-10), "graphical_lasso prec")
gc = GraphicalLassoCV(alphas=3, n_refinements=2, cv=3).fit(Z)
check(close([gc.alpha_], [glcv_alpha], 1e-9, 0.0), "glasso cv alpha"); check(close(gc.precision_, glcv_prec, 1e-8, 1e-10), "glasso cv prec")

if failed:
    print("TEST FAILED", failed)
    sys.exit(1)
print("OK")
